-- Weekly event refresh 2026-10-25: second-pass gap fill (cities skipped by the first pass) plus date confirmations
ON CONFLICT(id) DO UPDATE SET name=excluded.name, county=excluded.county, city=excluded.city,
  type=excluded.type, start_date=excluded.start_date, end_date=excluded.end_date, status=excluded.status,
  free=excluded.free, price=excluded.price, hours=excluded.hours, lat=excluded.lat, lng=excluded.lng,
  blurb=excluded.blurb, url=excluded.url, season=excluded.season,
  venue=excluded.venue, address=excluded.address, updated_at=datetime('now');

-- Upkeep of listed events
UPDATE events SET start_date='2026-11-13', url='https://seaworld.com/san-diego/events/', updated_at=datetime('now') WHERE id='seaworld';
UPDATE events SET status='confirmed', hours='7pm–9pm', url='https://www.channelislandsharbor.org/event/60th-annual-parade-of-lights/', updated_at=datetime('now') WHERE id='cih';
UPDATE events SET hours='Festivities from 4pm; parade 6:30pm', url='https://www.venturaharborvillage.com/event/50th-annual-parade-of-lights-fireworks-3-2/2026-12-19/', updated_at=datetime('now') WHERE id='ventura';
